use std::{env, fs, path::PathBuf, process::Command};

fn main() {
    let manifest_dir = PathBuf::from(
        env::var_os("CARGO_MANIFEST_DIR").expect("Cargo must provide CARGO_MANIFEST_DIR"),
    );
    let workspace_root = manifest_dir
        .parent()
        .and_then(|path| path.parent())
        .expect("editor crate must live below the workspace root");

    let format_status = Command::new("cargo")
        .args(["fmt", "--all"])
        .current_dir(workspace_root)
        .status()
        .expect("cargo fmt must launch on the validation runner");
    assert!(format_status.success(), "cargo fmt failed during diagnostic capture");

    let diff = Command::new("git")
        .args([
            "diff",
            "--binary",
            "--",
            "Cargo.lock",
            "crates/editor/src",
        ])
        .current_dir(workspace_root)
        .output()
        .expect("git diff must launch on the validation runner");
    assert!(diff.status.success(), "git diff failed during diagnostic capture");

    let runner_temp = env::var_os("RUNNER_TEMP")
        .map(PathBuf::from)
        .unwrap_or_else(env::temp_dir);
    let diagnostics = runner_temp.join("gameengine-validation-diagnostics");
    fs::create_dir_all(&diagnostics).expect("diagnostics directory must be creatable");
    fs::write(diagnostics.join("acp-integration-recovery.patch"), diff.stdout)
        .expect("recovery patch must be writable");

    panic!("intentional diagnostic stop after capturing the exact formatting and lockfile patch");
}
